"""钱包持久化：只保存份额，磁盘上不存在完整私钥。

磁盘布局（data_dir 下）::

    wallets/<wallet_id>.json        钱包元数据 + 份额公钥（无私钥）
    shares/<wallet_id>/<share_id>.json
                                    单个份额（份额私钥以 hex 保存），一份一个文件
    signatures/<wallet_id>.json     该钱包已完成的签名请求（幂等去重）
    policies/<wallet_id>.json       该钱包的审批策略（required_approvals 等）
    requests/<wallet_id>.json       该钱包的签名请求审批单（状态机）
    rotations/<wallet_id>.json      该钱包的份额轮换记录（prepared/activating/active）
    rotation-staging/<wallet_id>/<rotation_id>/
                                    轮换暂存目录：新份额私钥文件（<share_id>.json），
                                    激活期间的旧份额/钱包元数据备份（*.bak.json），
                                    激活成功后整目录删除
    audit/<wallet_id>.json          该钱包的审计事件日志（seq 从 1 起仅追加，
                                    由 audit.AuditStore 维护）
    assets/<wallet_id>.json         该钱包的资产账本：asset-operations（操作
                                    状态机 pending/committed）与 assets（每个
                                    资产的 balance/version），同一文件原子写入
    asset-intents/<wallet_id>/<operation_id>.json
                                    资产提交的"提交意图"（可恢复事务日志）：
                                    仅在 commit 事务窗口内存在，提交完成即删；
                                    崩溃后启动恢复据此判定提交是否已落事件，
                                    决定补齐账本或回滚为 pending
    transaction-policies/<wallet_id>.json
                                    该钱包的冷热钱包交易策略
                                    （mode/max_delta/allowed_assets），
                                    只含标识与整数，不含任何私钥材料

关键安全性质：
- 元数据文件不含任何私钥材料；
- 每个文件至多包含一个 32 字节份额私钥，两个份额分文件存放，
  任何位置都不保存拼接/聚合后的完整私钥；
- 写入采用同目录临时文件 + os.replace 原子替换；
- 进程内用一把锁串行化写操作（ThreadingHTTPServer 下安全）。
"""

from __future__ import annotations

import json
import os
import re
import shutil
import tempfile
import threading
from typing import Optional

from .crypto import ShareKey, combine_public_keys, public_key_from_private

#: wallet_id / rotation_id / signing_request_id 允许的字符（同时杜绝路径穿越）
_SAFE_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")

#: share_id 允许的字符：轮换份额 id 为 <rotation_id>-share-N，最长 128+8
_SAFE_SHARE_ID = re.compile(r"^[A-Za-z0-9_-]{1,136}$")


def _check_id(kind: str, value: str) -> None:
    if not isinstance(value, str) or not _SAFE_ID.match(value):
        raise ValueError(f"invalid {kind}: {value!r}")


def _check_share_id(value: str) -> None:
    if not isinstance(value, str) or not _SAFE_SHARE_ID.match(value):
        raise ValueError(f"invalid share_id: {value!r}")


class DuplicateWalletError(Exception):
    """wallet_id 已存在。"""


class RecoveryError(Exception):
    """启动/运行时恢复无法把磁盘现场对账到一致状态。

    触发即说明数据目录损坏或被外部篡改，继续服务可能暴露半完成状态或
    写错密钥，因此调用方必须阻止服务就绪（fail-closed），不得静默跳过。
    """


class CorruptDataError(ValueError):
    """本应是 JSON 对象的持久化文件无法解析（损坏或被外部篡改）。

    是 ValueError 的子类：既有的宽松 ``except ValueError``（如把不可解析
    意图纳入对账、把损坏暂存判为无效）行为不变；业务/HTTP 边界则可据此
    把"解析异常"与"非法 id"区分开——前者 fail-closed（503/阻止就绪），
    后者才是 400。
    """


class WalletStore:
    """钱包、份额与已完成签名请求的文件存储。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._wallets_dir = os.path.join(data_dir, "wallets")
        self._shares_dir = os.path.join(data_dir, "shares")
        self._signatures_dir = os.path.join(data_dir, "signatures")
        self._policies_dir = os.path.join(data_dir, "policies")
        self._requests_dir = os.path.join(data_dir, "requests")
        self._rotations_dir = os.path.join(data_dir, "rotations")
        self._rotation_staging_dir = os.path.join(data_dir, "rotation-staging")
        self._assets_dir = os.path.join(data_dir, "assets")
        self._asset_intents_dir = os.path.join(data_dir, "asset-intents")
        self._transaction_policies_dir = os.path.join(
            data_dir, "transaction-policies"
        )
        os.makedirs(self._wallets_dir, exist_ok=True)
        os.makedirs(self._shares_dir, exist_ok=True)
        os.makedirs(self._signatures_dir, exist_ok=True)
        os.makedirs(self._policies_dir, exist_ok=True)
        os.makedirs(self._requests_dir, exist_ok=True)
        os.makedirs(self._rotations_dir, exist_ok=True)
        os.makedirs(self._rotation_staging_dir, exist_ok=True)
        os.makedirs(self._assets_dir, exist_ok=True)
        os.makedirs(self._asset_intents_dir, exist_ok=True)
        os.makedirs(self._transaction_policies_dir, exist_ok=True)
        self._lock = threading.Lock()

    @property
    def data_dir(self) -> str:
        return self._data_dir

    # ---- 内部工具 -------------------------------------------------------

    def _wallet_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._wallets_dir, wallet_id + ".json")

    def _share_path(self, wallet_id: str, share_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_share_id(share_id)
        return os.path.join(
            self._shares_dir, wallet_id, share_id + ".json"
        )

    def _signatures_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._signatures_dir, wallet_id + ".json")

    def _policy_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._policies_dir, wallet_id + ".json")

    def _requests_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._requests_dir, wallet_id + ".json")

    @staticmethod
    def _atomic_write(path: str, data: dict) -> None:
        directory = os.path.dirname(path)
        os.makedirs(directory, exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2, sort_keys=True)
                f.write("\n")
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except FileNotFoundError:
                pass
            raise

    @staticmethod
    def _read_json(path: str) -> Optional[dict]:
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except FileNotFoundError:
            return None
        except json.JSONDecodeError as exc:
            # 文件存在但损坏/被外部篡改：区别于"文件不存在"，按不可对账
            # 的数据损坏处理（CorruptDataError 是 ValueError 子类）。
            raise CorruptDataError(
                f"cannot parse JSON file {path!r}: {exc.msg}"
            ) from exc

    # ---- 钱包与份额 -----------------------------------------------------

    def create_wallet(
        self, wallet_id: str, shares: list[ShareKey], created_at: str
    ) -> None:
        """原子创建钱包元数据与各份额文件；重复时抛 DuplicateWalletError。"""
        meta_path = self._wallet_path(wallet_id)
        meta = {
            "wallet_id": wallet_id,
            "created_at": created_at,
            "public_key": b"".join(s.public_bytes for s in shares).hex(),
            "shares": [
                {"share_id": s.share_id, "public_key": s.public_bytes.hex()}
                for s in shares
            ],
        }
        share_records = [
            (
                self._share_path(wallet_id, s.share_id),
                {
                    "share_id": s.share_id,
                    "public_key": s.public_bytes.hex(),
                    # 仅该份额自己的私钥；系统中不存在完整私钥
                    "private_key": s.private_bytes.hex(),
                },
            )
            for s in shares
        ]
        with self._lock:
            if os.path.exists(meta_path):
                raise DuplicateWalletError(wallet_id)
            for path, record in share_records:
                self._atomic_write(path, record)
            self._atomic_write(meta_path, meta)

    def get_wallet(self, wallet_id: str) -> Optional[dict]:
        """返回钱包元数据（不含私钥），不存在返回 None。"""
        return self._read_json(self._wallet_path(wallet_id))

    def has_wallet(self, wallet_id: str) -> bool:
        return os.path.exists(self._wallet_path(wallet_id))

    def get_share(self, wallet_id: str, share_id: str) -> Optional[dict]:
        """返回单个份额记录（含该份额私钥 hex），不存在返回 None。"""
        return self._read_json(self._share_path(wallet_id, share_id))

    # ---- 签名请求 -------------------------------------------------------

    def save_signature(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> Optional[dict]:
        """原子地保存一条已完成签名。

        在同一把锁内先查重：若该 signing_request_id 已有结果，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("signing_request_id", signing_request_id)
        path = self._signatures_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(signing_request_id)
            if existing is not None:
                return existing
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_signature(
        self, wallet_id: str, signing_request_id: str
    ) -> Optional[dict]:
        """返回某签名请求的已有结果，不存在返回 None。"""
        _check_id("signing_request_id", signing_request_id)
        all_records = self._read_json(self._signatures_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(signing_request_id)

    # ---- 审批策略 -------------------------------------------------------

    def save_policy(self, wallet_id: str, policy: dict) -> None:
        """原子地写入（或覆盖）钱包的审批策略。"""
        path = self._policy_path(wallet_id)
        with self._lock:
            self._atomic_write(path, policy)

    def get_policy(self, wallet_id: str) -> Optional[dict]:
        """返回钱包的审批策略，未设置返回 None。"""
        return self._read_json(self._policy_path(wallet_id))

    # ---- 签名请求审批单 ---------------------------------------------------

    def create_request(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条签名请求审批单。

        在同一把锁内先查重：若该 signing_request_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(signing_request_id)
            if existing is not None:
                return existing
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_request(
        self, wallet_id: str, signing_request_id: str
    ) -> Optional[dict]:
        """返回某条签名请求审批单，不存在返回 None。"""
        _check_id("signing_request_id", signing_request_id)
        all_records = self._read_json(self._requests_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(signing_request_id)

    def update_request(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> None:
        """原子地覆盖一条已存在的签名请求审批单（状态机推进用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)

    # ---- 回滚（状态/事件原子性用）----------------------------------------

    def delete_policy(self, wallet_id: str) -> None:
        """删除钱包的审批策略文件（策略事件追加失败时回滚用）。"""
        path = self._policy_path(wallet_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    # ---- 冷热钱包交易策略 -----------------------------------------------

    def _transaction_policy_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(
            self._transaction_policies_dir, wallet_id + ".json"
        )

    def save_transaction_policy(self, wallet_id: str, policy: dict) -> None:
        """原子地写入（或覆盖）钱包的冷热钱包交易策略。

        文件只含 mode/max_delta/allowed_assets（标识与整数/字符串），
        不含任何私钥材料。
        """
        path = self._transaction_policy_path(wallet_id)
        with self._lock:
            self._atomic_write(path, policy)

    def get_transaction_policy(self, wallet_id: str) -> Optional[dict]:
        """返回钱包的冷热钱包交易策略，未设置返回 None。"""
        return self._read_json(self._transaction_policy_path(wallet_id))

    def delete_transaction_policy(self, wallet_id: str) -> None:
        """删除钱包的交易策略文件（首设时事件追加失败回滚用）。"""
        path = self._transaction_policy_path(wallet_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def delete_request(self, wallet_id: str, signing_request_id: str) -> None:
        """删除一条签名请求审批单（创建事件追加失败时回滚用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or signing_request_id not in all_records:
                return
            del all_records[signing_request_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    def delete_signature(self, wallet_id: str, signing_request_id: str) -> None:
        """删除一条已完成签名记录（签名事件追加失败时回滚用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._signatures_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or signing_request_id not in all_records:
                return
            del all_records[signing_request_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    # ---- 资产账本（asset-operations 与 assets）-----------------------------

    def _assets_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._assets_dir, wallet_id + ".json")

    def _read_asset_ledger(self, wallet_id: str) -> dict:
        """读取资产账本（无文件时返回空结构）。"""
        ledger = self._read_json(self._assets_path(wallet_id))
        if not isinstance(ledger, dict):
            ledger = {}
        operations = ledger.get("operations")
        if not isinstance(operations, dict):
            operations = {}
        assets = ledger.get("assets")
        if not isinstance(assets, dict):
            assets = {}
        return {"operations": operations, "assets": assets}

    def create_asset_operation(
        self, wallet_id: str, operation_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条资产操作记录。

        在同一把锁内先查重：若该 operation_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("operation_id", operation_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            existing = ledger["operations"].get(operation_id)
            if isinstance(existing, dict):
                return existing
            ledger["operations"][operation_id] = record
            self._atomic_write(path, ledger)
            return None

    def get_asset_operation(
        self, wallet_id: str, operation_id: str
    ) -> Optional[dict]:
        """返回某条资产操作记录，不存在返回 None。"""
        _check_id("operation_id", operation_id)
        record = self._read_asset_ledger(wallet_id)["operations"].get(
            operation_id
        )
        return dict(record) if isinstance(record, dict) else None

    def get_asset(self, wallet_id: str, asset_id: str) -> Optional[dict]:
        """返回某资产的账本记录（balance/version），不存在返回 None。"""
        _check_id("asset_id", asset_id)
        record = self._read_asset_ledger(wallet_id)["assets"].get(asset_id)
        return dict(record) if isinstance(record, dict) else None

    def commit_asset_operation(
        self,
        wallet_id: str,
        operation_id: str,
        operation_record: dict,
        asset_id: str,
        asset_record: dict,
    ) -> None:
        """原子地提交一条资产操作：操作记录与资产 balance/version 同文件
        一次写入（调用方须持有该钱包事务锁）。"""
        _check_id("operation_id", operation_id)
        _check_id("asset_id", asset_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            ledger["operations"][operation_id] = operation_record
            ledger["assets"][asset_id] = asset_record
            self._atomic_write(path, ledger)

    def restore_asset_operation(
        self,
        wallet_id: str,
        operation_id: str,
        operation_record: dict,
        asset_id: str,
        asset_record: Optional[dict],
    ) -> None:
        """提交事件追加失败时回滚：恢复操作记录与资产记录
        （asset_record 为 None 表示提交前该资产无账本记录，直接删除）。"""
        _check_id("operation_id", operation_id)
        _check_id("asset_id", asset_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            ledger["operations"][operation_id] = operation_record
            if asset_record is None:
                ledger["assets"].pop(asset_id, None)
            else:
                ledger["assets"][asset_id] = asset_record
            self._atomic_write(path, ledger)

    # ---- 资产提交意图（可恢复事务日志）-----------------------------------

    def _asset_intent_path(self, wallet_id: str, operation_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_id("operation_id", operation_id)
        return os.path.join(
            self._asset_intents_dir, wallet_id, operation_id + ".json"
        )

    def write_asset_commit_intent(
        self, wallet_id: str, operation_id: str, intent: dict
    ) -> None:
        """原子写入一条资产提交意图（commit 事务第一步）。

        意图记录只含标识与整数（operation_id/asset_id/delta、提交前后
        balance/version、事件 seq），不含任何私钥材料。
        """
        path = self._asset_intent_path(wallet_id, operation_id)
        with self._lock:
            self._atomic_write(path, intent)

    def get_asset_commit_intent(
        self, wallet_id: str, operation_id: str
    ) -> Optional[dict]:
        """返回某操作的提交意图，不存在返回 None。"""
        return self._read_json(self._asset_intent_path(wallet_id, operation_id))

    def delete_asset_commit_intent(
        self, wallet_id: str, operation_id: str
    ) -> None:
        """删除提交意图（commit 事务完成/中止的最后一步）。"""
        path = self._asset_intent_path(wallet_id, operation_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def list_asset_intent_wallet_ids(self) -> list[str]:
        """返回存在提交意图目录的全部 wallet_id。"""
        try:
            names = os.listdir(self._asset_intents_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(self._asset_intents_dir, name))
        )

    def list_asset_intents(self, wallet_id: str) -> list[tuple[str, Optional[dict]]]:
        """返回某钱包全部提交意图 (operation_id, intent|None)。

        intent 为 None 表示文件存在但 JSON 不可解析（原子写使正常流程
        不会出现，仅外部损坏时）：调用方据文件名的 operation_id 与账本/
        审计对账即可，不依赖意图内容。
        """
        _check_id("wallet_id", wallet_id)
        base = os.path.join(self._asset_intents_dir, wallet_id)
        try:
            names = os.listdir(base)
        except (FileNotFoundError, NotADirectoryError):
            return []
        result: list[tuple[str, Optional[dict]]] = []
        for name in names:
            if not name.endswith(".json"):
                continue
            operation_id = name[: -len(".json")]
            if not _SAFE_ID.match(operation_id):
                # 非预期文件：不纳入恢复，也不删除业务数据
                continue
            try:
                data = self._read_json(os.path.join(base, name))
            except ValueError:
                # JSON 不可解析（原子写使正常流程不会出现，仅外部损坏）
                data = None
            result.append((operation_id, data if isinstance(data, dict) else None))
        return sorted(result, key=lambda item: item[0])

    # ---- 份额文件与钱包元数据（轮换激活用）--------------------------------

    def save_share(self, wallet_id: str, record: dict) -> None:
        """原子地写入（或覆盖）一个份额文件（含该份额私钥 hex）。"""
        path = self._share_path(wallet_id, record["share_id"])
        with self._lock:
            self._atomic_write(path, record)

    def delete_share(self, wallet_id: str, share_id: str) -> None:
        """删除一个份额文件（轮换激活换下旧份额 / 回滚清理新份额用）。"""
        path = self._share_path(wallet_id, share_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def save_wallet_meta(self, wallet_id: str, meta: dict) -> None:
        """原子地覆盖钱包元数据文件（无私钥；轮换激活/回滚用）。"""
        path = self._wallet_path(wallet_id)
        with self._lock:
            self._atomic_write(path, meta)

    # ---- 份额轮换记录 -----------------------------------------------------

    def _rotations_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._rotations_dir, wallet_id + ".json")

    def create_rotation(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条份额轮换记录。

        在同一把锁内先查重：若该 rotation_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(rotation_id)
            if existing is not None:
                return existing
            all_records[rotation_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_rotation(
        self, wallet_id: str, rotation_id: str
    ) -> Optional[dict]:
        """返回某条份额轮换记录，不存在返回 None。"""
        _check_id("rotation_id", rotation_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(rotation_id)

    def list_rotations(self, wallet_id: str) -> list[dict]:
        """返回该钱包的全部份额轮换记录（无文件时返回 []）。"""
        _check_id("wallet_id", wallet_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not all_records:
            return []
        return [
            dict(record)
            for record in all_records.values()
            if isinstance(record, dict)
        ]

    def update_rotation(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> None:
        """原子地覆盖一条已存在的份额轮换记录（状态机推进用）。"""
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            all_records[rotation_id] = record
            self._atomic_write(path, all_records)

    def delete_rotation(self, wallet_id: str, rotation_id: str) -> None:
        """删除一条份额轮换记录（准备事件追加失败时回滚用）。"""
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or rotation_id not in all_records:
                return
            del all_records[rotation_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    # ---- 轮换暂存目录（新份额私钥 + 激活备份）------------------------------

    def _staging_dir(self, wallet_id: str, rotation_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_id("rotation_id", rotation_id)
        return os.path.join(
            self._rotation_staging_dir, wallet_id, rotation_id
        )

    def _staging_share_path(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> str:
        _check_share_id(share_id)
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id), share_id + ".json"
        )

    def _staging_backup_path(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> str:
        _check_share_id(share_id)
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id),
            share_id + ".bak.json",
        )

    def _staging_wallet_backup_path(
        self, wallet_id: str, rotation_id: str
    ) -> str:
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id), "wallet.bak.json"
        )

    def save_staging_share(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> None:
        """把一个新份额（含私钥）写入轮换暂存目录，一份一个文件。"""
        path = self._staging_share_path(
            wallet_id, rotation_id, record["share_id"]
        )
        with self._lock:
            self._atomic_write(path, record)

    def get_staging_share(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> Optional[dict]:
        """返回暂存的新份额记录，不存在返回 None。"""
        return self._read_json(
            self._staging_share_path(wallet_id, rotation_id, share_id)
        )

    def save_activation_backups(
        self,
        wallet_id: str,
        rotation_id: str,
        old_shares: list[dict],
        wallet_meta: dict,
    ) -> None:
        """激活前把旧份额文件与钱包元数据备份进暂存目录（回滚依据）。"""
        with self._lock:
            for record in old_shares:
                self._atomic_write(
                    self._staging_backup_path(
                        wallet_id, rotation_id, record["share_id"]
                    ),
                    record,
                )
            self._atomic_write(
                self._staging_wallet_backup_path(wallet_id, rotation_id),
                wallet_meta,
            )

    def delete_activation_backups(
        self, wallet_id: str, rotation_id: str
    ) -> None:
        """删除激活备份（*.bak.json），保留暂存的新份额文件。"""
        staging = self._staging_dir(wallet_id, rotation_id)
        with self._lock:
            try:
                names = os.listdir(staging)
            except FileNotFoundError:
                return
            for name in names:
                if name.endswith(".bak.json"):
                    try:
                        os.unlink(os.path.join(staging, name))
                    except FileNotFoundError:
                        pass

    def delete_staging(self, wallet_id: str, rotation_id: str) -> None:
        """删除整个轮换暂存目录（激活成功后清理暂存与备份）。"""
        staging = self._staging_dir(wallet_id, rotation_id)
        with self._lock:
            shutil.rmtree(staging, ignore_errors=True)

    # ---- 启动恢复：未完成的激活先回滚，轮换残留按有效性判定 --------------

    def list_rotation_wallet_ids(self) -> list[str]:
        """返回拥有轮换记录文件的全部 wallet_id。

        只纳入匹配安全 id 的正式记录文件，忽略原子写残留的
        ``.tmp-*.json`` 等临时文件，避免把临时文件名当成 wallet_id。
        """
        try:
            names = os.listdir(self._rotations_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _SAFE_ID.match(name[: -len(".json")])
        )

    def list_staging_wallet_ids(self) -> list[str]:
        """返回轮换暂存根目录下出现过的全部 wallet_id（含无记录文件的）。
        只纳入匹配安全 id 的目录名，忽略任何杂项目录。"""
        try:
            names = os.listdir(self._rotation_staging_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(self._rotation_staging_dir, name))
        )

    def list_staging_rotation_ids(self, wallet_id: str) -> list[str]:
        """返回某钱包暂存目录下的全部 rotation_id 目录名。"""
        _check_id("wallet_id", wallet_id)
        base = os.path.join(self._rotation_staging_dir, wallet_id)
        try:
            names = os.listdir(base)
        except (FileNotFoundError, NotADirectoryError):
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(base, name))
        )

    def list_rotation_entries(self, wallet_id: str) -> list[tuple[str, dict]]:
        """返回 (记录键, 记录) 对；记录键即删除时使用的 rotation_id。"""
        _check_id("wallet_id", wallet_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not isinstance(all_records, dict):
            return []
        return [
            (key, record)
            for key, record in all_records.items()
            if isinstance(key, str) and isinstance(record, dict)
        ]

    def rollback_activation_files(
        self, wallet_id: str, rotation_record: dict
    ) -> None:
        """用暂存目录中的备份恢复钱包元数据与旧份额文件，并删除已换入的
        新份额文件。备份缺失（崩溃发生在备份写入前）时各步自动跳过。"""
        rotation_id = rotation_record["rotation_id"]
        wallet_backup = self._read_json(
            self._staging_wallet_backup_path(wallet_id, rotation_id)
        )
        if wallet_backup is not None:
            self.save_wallet_meta(wallet_id, wallet_backup)
        staging = self._staging_dir(wallet_id, rotation_id)
        try:
            names = os.listdir(staging)
        except FileNotFoundError:
            names = []
        for name in names:
            if name.endswith(".bak.json") and name != "wallet.bak.json":
                share_record = self._read_json(os.path.join(staging, name))
                if isinstance(share_record, dict) and isinstance(
                    share_record.get("share_id"), str
                ):
                    self.save_share(wallet_id, share_record)
        for share_id in rotation_record.get("share_ids", []):
            if isinstance(share_id, str):
                self.delete_share(wallet_id, share_id)

    @staticmethod
    def _rotation_record_shape_ok(record: dict) -> bool:
        """轮换记录的基本形状校验（启动恢复判定"无效记录"用）。"""
        rotation_id = record.get("rotation_id")
        if not isinstance(rotation_id, str) or not _SAFE_ID.match(rotation_id):
            return False
        if record.get("state") not in ("prepared", "activating", "active"):
            return False
        share_ids = record.get("share_ids")
        if (
            not isinstance(share_ids, list)
            or len(share_ids) != 2
            or any(
                not isinstance(sid, str) or not _SAFE_SHARE_ID.match(sid)
                for sid in share_ids
            )
        ):
            return False
        public_key = record.get("public_key")
        if not isinstance(public_key, str):
            return False
        try:
            if len(bytes.fromhex(public_key)) != 64:
                return False
        except ValueError:
            return False
        return True

    def _prepared_staging_valid(self, wallet_id: str, record: dict) -> bool:
        """判定 prepared 轮换的暂存目录是否完整有效。

        仅当全部满足时保留：目录名与 rotation_id 一致（由路径构造保证）、
        目录内恰有记录中两个 share_ids 对应的份额文件（无多无缺）、每个
        文件 JSON 可解析、share_id 与记录一致、public_key 恰为 32 字节、
        私钥恰为 32 字节且能推导出该 public_key、两个份额公钥按序拼接
        等于记录中的钱包 public_key。
        """
        rotation_id = record["rotation_id"]
        share_ids = list(record["share_ids"])
        staging = self._staging_dir(wallet_id, rotation_id)
        try:
            names = set(os.listdir(staging))
        except (FileNotFoundError, NotADirectoryError):
            return False
        if names != {sid + ".json" for sid in share_ids}:
            return False
        share_public_keys: list[bytes] = []
        for share_id in share_ids:
            try:
                data = self._read_json(
                    os.path.join(staging, share_id + ".json")
                )
            except (ValueError, OSError):
                # JSON 不可解析 / 读取失败
                return False
            if not isinstance(data, dict) or data.get("share_id") != share_id:
                return False
            public_hex = data.get("public_key")
            private_hex = data.get("private_key")
            if not isinstance(public_hex, str) or not isinstance(
                private_hex, str
            ):
                return False
            try:
                public_bytes = bytes.fromhex(public_hex)
                private_bytes = bytes.fromhex(private_hex)
            except ValueError:
                return False
            if len(public_bytes) != 32 or len(private_bytes) != 32:
                return False
            try:
                if public_key_from_private(private_bytes) != public_bytes:
                    return False
            except ValueError:
                return False
            share_public_keys.append(public_bytes)
        return (
            combine_public_keys(share_public_keys).hex()
            == record["public_key"]
        )

    def _load_backup_wallet_meta(
        self, wallet_id: str, rotation_id: str
    ) -> Optional[dict]:
        return self._read_json(
            self._staging_wallet_backup_path(wallet_id, rotation_id)
        )

    def _assert_rollback_possible(
        self, wallet_id: str, record: dict
    ) -> None:
        """事件未落盘的激活回滚前，确认能安全恢复旧钱包与旧份额。

        - 钱包元数据仍指向旧公钥（换入尚未发生）：只要当前元数据里的
          旧份额文件都还在即可，换入的新份额会在回滚时删除，无需备份；
        - 元数据已指向新公钥（换入已发生）：必须有激活前的钱包/份额
          备份作为权威回滚依据；
        - 元数据旧但旧份额缺失：同样必须有备份。
        无法安全恢复时抛 RecoveryError（fail-closed），绝不猜写旧密钥。
        """
        rotation_id = record["rotation_id"]
        current = self.get_wallet(wallet_id)
        if not isinstance(current, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} metadata missing during rollback"
            )
        swapped = current.get("public_key") == record["public_key"]
        if swapped:
            if self._load_backup_wallet_meta(wallet_id, rotation_id) is None:
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} "
                    "has no activation backup to roll back"
                )
            return
        # 元数据仍旧：旧份额必须完整，否则需备份才能恢复
        shares = current.get("shares")
        old_ids = [
            s.get("share_id")
            for s in shares
            if isinstance(s, dict)
            and s.get("share_id") not in record["share_ids"]
        ] if isinstance(shares, list) else []
        missing = [
            sid
            for sid in old_ids
            if isinstance(sid, str) and self.get_share(wallet_id, sid) is None
        ]
        if missing and self._load_backup_wallet_meta(
            wallet_id, rotation_id
        ) is None:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rotation_id!r} lost "
                f"in-use shares {missing!r} without backup"
            )

    def _rollback_incomplete_activation(
        self, wallet_id: str, record: dict
    ) -> dict:
        """事件未落盘的激活：回滚旧钱包元数据与旧份额、删除已换入的
        新份额，状态置回 prepared，并清掉激活备份、保留经校验的暂存份额。
        返回置回 prepared 的记录。"""
        self.rollback_activation_files(wallet_id, record)
        rotation_id = record["rotation_id"]
        restored = {
            k: v
            for k, v in record.items()
            if k != "previous_public_key"
        }
        restored["state"] = "prepared"
        self.update_rotation(wallet_id, rotation_id, restored)
        self.delete_activation_backups(wallet_id, rotation_id)
        return restored

    def forward_complete_activation(
        self, wallet_id: str, record: dict, event: dict
    ) -> None:
        """share_rotation_activated 事件已落盘：提交不可撤回，把现场前滚
        成唯一 active 结果并清理全部暂存/备份残留。缺新份额或现场自相
        矛盾时抛 RecoveryError（fail-closed），绝不猜写密钥。"""
        rotation_id = record["rotation_id"]
        details = event.get("details")
        if not isinstance(details, dict) or details.get("public_key") != record[
            "public_key"
        ]:
            raise RecoveryError(
                f"rotation {rotation_id!r} activated event does not match record"
            )

        new_share_records: list[dict] = []
        for share_id in record["share_ids"]:
            staged = self.get_share(wallet_id, share_id)
            if staged is None:
                # 崩溃可能发生在新份额全部换入前：暂存里仍有新份额
                staged = self.get_staging_share(
                    wallet_id, rotation_id, share_id
                )
            if not isinstance(staged, dict) or staged.get(
                "share_id"
            ) != share_id:
                raise RecoveryError(
                    f"rotation {rotation_id!r} missing new share {share_id!r}"
                )
            new_share_records.append(staged)

        # 前滚绝不猜写密钥：逐份校验 32 字节私钥能推导出对应公钥，
        # 且两份新公钥按序拼接恰为已提交事件里的钱包公钥。
        new_public_keys: list[bytes] = []
        for staged in new_share_records:
            public_hex = staged.get("public_key")
            private_hex = staged.get("private_key")
            if not isinstance(public_hex, str) or not isinstance(
                private_hex, str
            ):
                raise RecoveryError(
                    f"rotation {rotation_id!r} malformed new share"
                )
            try:
                public_bytes = bytes.fromhex(public_hex)
                private_bytes = bytes.fromhex(private_hex)
            except ValueError:
                raise RecoveryError(
                    f"rotation {rotation_id!r} non-hex new share"
                )
            if len(public_bytes) != 32 or len(private_bytes) != 32:
                raise RecoveryError(
                    f"rotation {rotation_id!r} bad-length new share"
                )
            try:
                if public_key_from_private(private_bytes) != public_bytes:
                    raise RecoveryError(
                        f"rotation {rotation_id!r} new share key mismatch"
                    )
            except ValueError:
                raise RecoveryError(
                    f"rotation {rotation_id!r} invalid new share private key"
                )
            new_public_keys.append(public_bytes)
        if (
            combine_public_keys(new_public_keys).hex()
            != record["public_key"]
        ):
            raise RecoveryError(
                f"rotation {rotation_id!r} new shares do not match "
                "committed public_key"
            )

        current_meta = self.get_wallet(wallet_id)
        backup_meta = self._read_json(
            self._staging_wallet_backup_path(wallet_id, rotation_id)
        )

        # 旧份额 id 集合：激活前备份的 wallet.bak.json 是权威旧清单；
        # 当前元数据若仍指向旧公钥，也纳入待删除集合。
        old_share_ids: set[str] = set()
        if isinstance(backup_meta, dict) and isinstance(
            backup_meta.get("shares"), list
        ):
            for entry in backup_meta["shares"]:
                if isinstance(entry, dict) and isinstance(
                    entry.get("share_id"), str
                ):
                    old_share_ids.add(entry["share_id"])
        if (
            isinstance(current_meta, dict)
            and current_meta.get("public_key") != record["public_key"]
            and isinstance(current_meta.get("shares"), list)
        ):
            for entry in current_meta["shares"]:
                if isinstance(entry, dict) and isinstance(
                    entry.get("share_id"), str
                ):
                    old_share_ids.add(entry["share_id"])
        old_share_ids.difference_update(record["share_ids"])

        previous_public_key = record.get("previous_public_key")
        if not isinstance(previous_public_key, str) and isinstance(
            backup_meta, dict
        ):
            previous_public_key = backup_meta.get("public_key")
        if not isinstance(previous_public_key, str) and isinstance(
            current_meta, dict
        ) and current_meta.get("public_key") != record["public_key"]:
            previous_public_key = current_meta.get("public_key")
        if not isinstance(previous_public_key, str):
            raise RecoveryError(
                f"rotation {rotation_id!r} cannot determine previous_public_key"
            )

        base_meta = current_meta if isinstance(current_meta, dict) else backup_meta
        if not isinstance(base_meta, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} metadata missing during roll-forward"
            )
        new_meta = dict(base_meta)
        new_meta["wallet_id"] = wallet_id
        new_meta["shares"] = [
            {"share_id": r["share_id"], "public_key": r["public_key"]}
            for r in new_share_records
        ]
        new_meta["public_key"] = record["public_key"]
        active_record = dict(record)
        active_record["state"] = "active"
        active_record["previous_public_key"] = previous_public_key

        # 前滚：新份额、钱包元数据、删除残留旧份额、active 状态
        for share_record in new_share_records:
            self.save_share(wallet_id, share_record)
        self.save_wallet_meta(wallet_id, new_meta)
        for share_id in old_share_ids:
            if _SAFE_SHARE_ID.match(share_id):
                self.delete_share(wallet_id, share_id)
        self.update_rotation(wallet_id, rotation_id, active_record)
        # 激活已生效：暂存的新份额副本与全部备份必须清干净
        self.delete_staging(wallet_id, rotation_id)

    def recover_wallet_rotation(
        self,
        wallet_id: str,
        activated: Optional[dict[str, dict]] = None,
    ) -> None:
        """按钱包恢复轮换现场（调用方须持有该钱包的跨进程事务锁）。

        以 share_rotation_activated 审计事件是否已持久化作为激活是否生效
        的唯一判据（activated 为 {rotation_id: event}）：

        - 事件在：激活已提交，无论记录停在 activating/active、暂存或
          备份是否已清理，都把钱包元数据/在用份额/轮换状态前滚为唯一
          active 结果并清理全部残留，不重复记事件；
        - 事件不在：activating/active 一律回滚为 prepared（恢复旧公钥与
          旧份额、删除换入的新份额），再按 prepared 规则校验暂存；
          缺少回滚所需备份时抛 RecoveryError 阻止就绪，绝不静默；
        - prepared：暂存经密码学校验通过才保留，否则连记录带暂存删除；
        - 无效记录：安全删除记录及其暂存目录；
        - 孤儿暂存目录：安全删除。

        全程不新增审计事件、不分配 seq；被删除暂存私钥不留副本。
        """
        _check_id("wallet_id", wallet_id)
        activated = activated or {}
        kept_prepared: set[str] = set()
        for key, record in self.list_rotation_entries(wallet_id):
            rotation_id = record.get("rotation_id")
            if not self._rotation_record_shape_ok(record):
                # 无效记录：连记录带暂存一起安全删除
                self.delete_rotation(wallet_id, key)
                if isinstance(rotation_id, str) and _SAFE_ID.match(
                    rotation_id
                ):
                    self.delete_staging(wallet_id, rotation_id)
                continue
            rotation_id = record["rotation_id"]
            event = activated.get(rotation_id)
            if event is not None:
                # 激活事件已落盘：保持 active、前滚补齐、清理全部残留
                self.forward_complete_activation(wallet_id, record, event)
                continue
            if record["state"] in ("activating", "active"):
                # 激活状态已写入但事件未落盘：提交未生效，无论记录停在
                # activating 还是 active，都恢复旧公钥与旧份额、置回
                # prepared，保留经校验有效的暂存份额。
                self._assert_rollback_possible(wallet_id, record)
                record = self._rollback_incomplete_activation(
                    wallet_id, record
                )
            # prepared（含刚回滚的）：暂存经密码学校验通过才保留
            if self._prepared_staging_valid(wallet_id, record):
                kept_prepared.add(rotation_id)
            else:
                # 暂存缺失/损坏/不匹配：记录与残留一起安全删除，
                # 绝不留下来路不明的私钥副本
                self.delete_rotation(wallet_id, rotation_id)
                self.delete_staging(wallet_id, rotation_id)
        # 孤儿暂存目录：没有对应有效 prepared 记录的一律安全删除
        for rotation_id in self.list_staging_rotation_ids(wallet_id):
            if rotation_id not in kept_prepared:
                self.delete_staging(wallet_id, rotation_id)

    def recover_incomplete_activations(
        self,
        activated: Optional[dict[str, dict]] = None,
    ) -> None:
        """启动恢复（无跨进程锁的独立入口；serve 使用 service 层的加锁
        编排）。activated 为各钱包激活事件映射；为 None 时从审计日志读取。
        恢复失败向上抛出 RecoveryError/OSError，由调用方阻止服务就绪。"""
        from .audit import AuditStore, TYPE_SHARE_ROTATION_ACTIVATED

        wallet_ids = sorted(
            set(self.list_rotation_wallet_ids())
            | set(self.list_staging_wallet_ids())
        )
        for wallet_id in wallet_ids:
            wallet_activated = activated
            if wallet_activated is None:
                events = AuditStore(self.data_dir).list_events(wallet_id)
                wallet_activated = {}
                for e in events:
                    if e.get("type") != TYPE_SHARE_ROTATION_ACTIVATED:
                        continue
                    details = e.get("details")
                    rid = (
                        details.get("rotation_id")
                        if isinstance(details, dict)
                        else None
                    )
                    if isinstance(rid, str):
                        wallet_activated[rid] = e
            self.recover_wallet_rotation(wallet_id, wallet_activated)

"""门限签名业务逻辑（与 HTTP 框架无关）。

规则：
- 建钱包：shares 必须恰为 2，否则 400；wallet_id 重复返回 409；
  成功生成两个独立份额并返回钱包公钥与两个 share_id（201）。
- 查询：不存在返回 404，成功返回 public_key 与 created_at。
- 签名：服务端不代替任何一方签名，只校验两个份额持有人提交上来的
  Ed25519 份额签名，两份齐备且全部校验通过才聚合返回（201）；
  缺份、份额不对、签名校验失败一律 400；同一 signing_request_id
  重复提交直接返回已有签名（200，幂等）。
"""

from __future__ import annotations

import re
import threading
from datetime import datetime, timedelta, timezone

from . import audit, crypto
from .audit import AuditStore
from .flock import FileLock, wallet_lock_path
from .store import (
    CorruptDataError,
    DuplicateWalletError,
    RecoveryError,
    WalletStore,
)

#: 两方门限：份额数固定为 2
REQUIRED_SHARES = 2

#: 服务端为两个份额生成的固定标识（按此顺序聚合公钥与签名）
SHARE_IDS = ("share-1", "share-2")

#: 审批策略允许的 required_approvals 取值
ALLOWED_REQUIRED_APPROVALS = (1, 2)

#: 冷热钱包交易策略允许的 mode 取值
TRANSACTION_POLICY_MODES = ("hot", "cold")

#: approve/reject 附言 reason 的最大长度
MAX_REASON_LENGTH = 1024

#: rotation_id 允许的字符（与存储层安全 id 一致）
ROTATION_ID_RE = re.compile(r"^[A-Za-z0-9_-]{1,128}$")


class ServiceError(Exception):
    """业务错误，携带 HTTP 状态码与错误信息。"""

    def __init__(self, status: int, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.message = message


def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _parse_iso(value: str) -> datetime:
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


class _WalletTransactionLock:
    """每钱包事务锁：进程内 threading.Lock + 跨进程文件锁的组合。

    同一 data-dir 可被多个服务进程共用；状态变更与审计追加必须在这把
    组合锁内完成，跨进程互斥由 flock 保证，进程异常退出后内核自动
    释放文件锁，不会被陈旧锁阻塞。
    """

    def __init__(self, thread_lock: threading.Lock, file_lock: FileLock) -> None:
        self._thread_lock = thread_lock
        self._file_lock = file_lock

    def __enter__(self) -> "_WalletTransactionLock":
        self._thread_lock.acquire()
        try:
            self._file_lock.acquire()
        except BaseException:
            self._thread_lock.release()
            raise
        return self

    def __exit__(self, *exc_info: object) -> None:
        try:
            self._file_lock.release()
        finally:
            self._thread_lock.release()


class WalletService:
    """建钱包、查询钱包、校验并聚合两份额签名。"""

    def __init__(self, store: WalletStore) -> None:
        self._store = store
        self._audit = AuditStore(store.data_dir)
        # 每钱包一把事务锁：串行化同一钱包的"状态变更 + 审计事件"，
        # ThreadingHTTPServer 并发下保证状态与事件原子、懒过期只记一次。
        self._wallet_locks: dict[str, threading.Lock] = {}
        self._wallet_locks_guard = threading.Lock()
        # 启动恢复：崩溃时停留在 activating 的轮换先回滚为 prepared，
        # 轮换残留按有效性判定保留或安全删除，然后才对外服务。
        # 同一 data-dir 可能有另一存活进程正在服务，因此每个钱包的恢复
        # 都在其跨进程事务锁内进行：对方在途的激活/签名提交完成后才
        # 判定现场，对方已崩溃时 flock 自动释放、不会阻塞恢复。
        self._recover_on_startup()

    def _thread_lock_for(self, wallet_id: str) -> threading.Lock:
        with self._wallet_locks_guard:
            lock = self._wallet_locks.get(wallet_id)
            if lock is None:
                lock = threading.Lock()
                self._wallet_locks[wallet_id] = lock
            return lock

    def _wallet_lock(self, wallet_id: str) -> _WalletTransactionLock:
        """返回该钱包的事务锁上下文管理器（进程内 + 跨进程）。

        wallet_id 含非法字符时抛 ValueError（与存储层一致）。
        """
        return _WalletTransactionLock(
            self._thread_lock_for(wallet_id),
            FileLock(wallet_lock_path(self._store.data_dir, wallet_id)),
        )

    def _recover_on_startup(self) -> None:
        """启动恢复编排：逐个钱包在其跨进程事务锁内恢复轮换现场与未完成
        的资产提交事务。对外服务前必须完成，使任何查询/重放都读不到
        半完成状态。

        任一钱包恢复失败（RecoveryError/OSError）都向上抛出，由调用方阻止
        服务就绪（fail-closed）：绝不静默跳过带着损坏现场对外服务。"""
        wallet_ids = sorted(
            set(self._store.list_rotation_wallet_ids())
            | set(self._store.list_staging_wallet_ids())
            | set(self._store.list_asset_intent_wallet_ids())
        )
        for wallet_id in wallet_ids:
            with self._wallet_lock(wallet_id):
                self._recover_wallet(wallet_id)

    def _activated_rotations(self, wallet_id: str) -> dict[str, dict]:
        """该钱包已落盘的 share_rotation_activated 事件映射。"""
        return self._audit.activated_rotation_events(wallet_id)

    def _recover_wallet(self, wallet_id: str) -> None:
        """在已持有该钱包事务锁的前提下，恢复轮换现场与未完成的资产提交。

        两者以同一把钱包锁串行，任何一个失败都向上抛出（RecoveryError/
        OSError），由调用方决定阻止就绪或把请求转成 503，绝不静默。

        损坏 JSON / 形状异常在存储层表现为 ValueError：恢复无法对账时同样
        fail-closed，统一转成 RecoveryError，绝不把 ValueError 漏给调用方
        当成普通参数错误。"""
        try:
            self._store.recover_wallet_rotation(
                wallet_id, self._activated_rotations(wallet_id)
            )
            self._recover_wallet_asset_commits(wallet_id)
        except RecoveryError:
            raise
        except (OSError, ValueError) as exc:
            raise RecoveryError(
                f"wallet {wallet_id!r} cannot be reconciled: {exc}"
            ) from exc

    def _heal_wallet(self, wallet_id: str) -> None:
        """持锁后自愈他进程崩溃遗留的现场（懒恢复，fail-closed）。

        常驻进程不会重跑启动恢复；为使任何查询/重放永远读不到他进程
        留下的半完成激活或半完成提交，业务操作在拿到钱包事务锁后先调用
        本方法。在途事务必持同锁，故这里看到的残留只能来自崩溃进程：

        - 资产提交意图残留：按提交事件是否落盘前滚或回滚；
        - activating 记录：激活事务窗口内的残留，按激活事件前滚/回滚；
        - active 记录但暂存/备份仍残留、或激活事件缺失：崩溃现场，
          按事件前滚补齐或（事件在却无法补齐时）fail-closed；
        - 无任何记录对应的孤儿暂存目录：安全删除。

        静止现场不触发恢复：prepared（暂存完整待激活）与干净完成的
        active（事件在、暂存已清空）。对账失败向上抛出
        RecoveryError/OSError，绝不静默继续。检测读取本身遇到损坏 JSON/
        形状异常（ValueError）时无法判断现场是否静止，按不可对账处理，
        交由 _recover_wallet fail-closed。
        """
        try:
            if self._store.list_asset_intents(wallet_id):
                self._recover_wallet(wallet_id)
                return
            rotations = self._store.list_rotations(wallet_id)
            staging_ids = set(self._store.list_staging_rotation_ids(wallet_id))
            needs_recovery = False
            active_check = False
            for record in rotations:
                state = record.get("state")
                rid = record.get("rotation_id")
                if state == "activating":
                    needs_recovery = True
                elif state == "active":
                    # 干净完成的 active：事件在且暂存已清空。暂存残留或
                    # 事件缺失才是崩溃现场（后者需读审计判定）。
                    if rid in staging_ids:
                        needs_recovery = True
                    else:
                        active_check = True
                elif state == "prepared" and isinstance(rid, str):
                    # prepared 的暂存目录是预期现场，不算孤儿
                    staging_ids.discard(rid)
            if not needs_recovery and active_check:
                activated = self._activated_rotations(wallet_id)
                for record in rotations:
                    if (
                        record.get("state") == "active"
                        and record.get("rotation_id") not in activated
                    ):
                        needs_recovery = True
                        break
            if not needs_recovery and staging_ids:
                # 无对应 prepared 记录的孤儿暂存目录
                needs_recovery = True
            if needs_recovery:
                self._recover_wallet(wallet_id)
        except RecoveryError:
            raise
        except (OSError, ValueError) as exc:
            # 检测/对账阶段读到无法解析的现场：不能假定静止，fail-closed
            raise RecoveryError(
                f"wallet {wallet_id!r} cannot be reconciled: {exc}"
            ) from exc

    @staticmethod
    def _audit_event(
        event_type: str,
        request_id=None,
        actor_id=None,
        reason=None,
        details=None,
    ) -> dict:
        """构造审计事件（seq 由 AuditStore 分配）。"""
        return {
            "type": event_type,
            "at": _utc_now_iso(),
            "request_id": request_id,
            "actor_id": actor_id,
            "reason": reason,
            "details": details,
        }

    def _emit(self, wallet_id: str, event: dict) -> None:
        self._audit.append_event(wallet_id, event)

    # ---- 建钱包 ---------------------------------------------------------

    def create_wallet(self, wallet_id: object, shares: object) -> dict:
        if not isinstance(wallet_id, str) or not wallet_id:
            raise ServiceError(400, "wallet_id must be a non-empty string")
        # bool 是 int 的子类，必须先排除；2.0 == 2，必须要求真正的 int
        if not isinstance(shares, int) or isinstance(shares, bool):
            raise ServiceError(400, "shares must equal 2")
        if shares != REQUIRED_SHARES:
            raise ServiceError(400, "shares must equal 2")
        try:
            share_keys = [crypto.generate_share_key(sid) for sid in SHARE_IDS]
            # 跨进程防重：同一 data-dir 上多个服务进程并发建同名钱包时，
            # 只有一个能在事务锁内提交成功
            with self._wallet_lock(wallet_id):
                self._store.create_wallet(
                    wallet_id, share_keys, _utc_now_iso()
                )
        except DuplicateWalletError:
            raise ServiceError(409, f"wallet {wallet_id!r} already exists")
        except ValueError:
            # wallet_id 含非法字符
            raise ServiceError(400, "invalid wallet_id")
        public_key = crypto.combine_public_keys(
            [k.public_bytes for k in share_keys]
        )
        return {
            "wallet_id": wallet_id,
            "public_key": public_key.hex(),
            "share_ids": list(SHARE_IDS),
        }

    # ---- 查询钱包 -------------------------------------------------------

    def get_wallet(self, wallet_id: str) -> dict:
        try:
            with self._wallet_lock(wallet_id):
                # 查询前先自愈他进程崩溃遗留的激活现场，绝不把换了一半
                # 的公钥/份额经 GET 暴露出去
                self._heal_wallet(wallet_id)
                record = self._store.get_wallet(wallet_id)
        except CorruptDataError:
            # 钱包元数据损坏：fail-closed（由 HTTP 边界转 503）
            raise
        except ValueError:
            raise ServiceError(400, "invalid wallet_id")
        if record is None:
            raise ServiceError(404, f"wallet {wallet_id!r} not found")
        return {
            "wallet_id": record["wallet_id"],
            "public_key": record["public_key"],
            "created_at": record["created_at"],
        }

    def share_sign(
        self,
        wallet_id: str,
        share_id: object,
        signing_request_id: object,
        message: object,
    ) -> dict:
        """份额持有方本地签名（CLI share-sign 专用，不经网络）。

        在该钱包的事务锁内先做懒恢复（``_heal_wallet``），再依据钱包
        元数据中当前在用的 share_id 读取份额私钥并签名：绝不在轮换激活
        半完成、或份额已轮换失效时读到半换入/已删除的份额。恢复无法
        对账时向上抛 RecoveryError/OSError（fail-closed），由调用方输出
        JSON 错误并非零退出。

        份额文件损坏（JSON 不可解析、非对象、字段缺失、私钥非 hex、长度
        非法）或私钥推导不出记录中的份额公钥（被篡改）时，绝不基于不一致
        的密钥签名：统一抛 ServiceError(503) 与不含私钥/载荷的泛化信息。
        """
        if (
            not isinstance(signing_request_id, str)
            or not signing_request_id
        ):
            raise ServiceError(
                400, "signing_request_id must be a non-empty string"
            )
        if not isinstance(message, str):
            raise ServiceError(400, "message must be a string")
        with self._wallet_lock(wallet_id):
            # 懒恢复可能抛 RecoveryError/OSError（fail-closed），保持上抛。
            self._heal_wallet(wallet_id)
            try:
                wallet = self._store.get_wallet(wallet_id)
            except CorruptDataError:
                raise
            except ValueError:
                raise ServiceError(400, "invalid wallet_id")
            if wallet is None:
                raise ServiceError(404, f"wallet {wallet_id!r} not found")
            in_use = {
                s.get("share_id"): s.get("public_key")
                for s in wallet.get("shares", [])
                if isinstance(s, dict)
            }
            if not isinstance(share_id, str) or share_id not in in_use:
                raise ServiceError(
                    404,
                    f"share {share_id!r} of wallet {wallet_id!r} not found",
                )
            try:
                share = self._store.get_share(wallet_id, share_id)
            except CorruptDataError:
                # 份额文件损坏：由下方完整性校验统一报泛化 503
                share = None
            except ValueError:
                raise ServiceError(400, "invalid share_id")
            # 份额完整性校验：任何形状/编码/长度/密钥对应关系异常都视为
            # 数据损坏，fail-closed，绝不读出私钥盲目签名，也绝不把底层
            # 异常文本、私钥或签名载荷暴露给调用方。
            private_bytes = self._load_share_private_bytes(
                share, expected_share_id=share_id,
                expected_public_hex=in_use[share_id],
            )
            payload = crypto.build_payload(signing_request_id, message)
            try:
                signature = crypto.sign_share(private_bytes, payload)
            except (ValueError, TypeError):
                # 理论上 32 字节私钥不会触发，仍兜底避免 traceback
                raise ServiceError(
                    503, "share is unavailable, refusing to sign"
                )
            return {"share_id": share_id, "signature": signature.hex()}

    @staticmethod
    def _load_share_private_bytes(
        share: object, *, expected_share_id: str, expected_public_hex: object
    ) -> bytes:
        """从份额记录中取出经一致性校验的 32 字节私钥。

        校验记录为对象、share_id 一致、public_key/private_key 均为字符串、
        各自解码为 32 字节、私钥推导出的公钥恰为记录/在用公钥。任一不满足
        都抛 ServiceError(503) 泛化错误（数据损坏或被篡改），不含私钥。"""
        generic = "share is unavailable, refusing to sign"
        if not isinstance(share, dict):
            raise ServiceError(503, generic)
        if share.get("share_id") != expected_share_id:
            raise ServiceError(503, generic)
        public_hex = share.get("public_key")
        private_hex = share.get("private_key")
        if not isinstance(public_hex, str) or not isinstance(private_hex, str):
            raise ServiceError(503, generic)
        try:
            public_bytes = bytes.fromhex(public_hex)
            private_bytes = bytes.fromhex(private_hex)
        except ValueError:
            raise ServiceError(503, generic)
        if len(public_bytes) != 32 or len(private_bytes) != 32:
            raise ServiceError(503, generic)
        try:
            derived = crypto.public_key_from_private(private_bytes)
        except (ValueError, TypeError):
            raise ServiceError(503, generic)
        if derived != public_bytes:
            raise ServiceError(503, generic)
        # 份额记录的公钥还必须与钱包元数据中当前在用公钥一致
        if not isinstance(expected_public_hex, str):
            raise ServiceError(503, generic)
        try:
            in_use_public = bytes.fromhex(expected_public_hex)
        except ValueError:
            raise ServiceError(503, generic)
        if in_use_public != public_bytes:
            raise ServiceError(503, generic)
        return private_bytes

    # ---- 审批策略 -------------------------------------------------------

    def _get_wallet_or_404(self, wallet_id: str) -> dict:
        try:
            wallet = self._store.get_wallet(wallet_id)
        except CorruptDataError:
            # 钱包元数据损坏：fail-closed（由 HTTP 边界转 503），绝不
            # 当成普通 400 或返回半完成公钥
            raise
        except ValueError:
            raise ServiceError(400, "invalid wallet_id")
        if wallet is None:
            raise ServiceError(404, f"wallet {wallet_id!r} not found")
        return wallet

    def put_policy(
        self,
        wallet_id: str,
        required_approvals: object,
        timeout_seconds: object,
    ) -> dict:
        self._get_wallet_or_404(wallet_id)
        # bool 是 int 的子类，必须先排除
        if (
            not isinstance(required_approvals, int)
            or isinstance(required_approvals, bool)
            or required_approvals not in ALLOWED_REQUIRED_APPROVALS
        ):
            raise ServiceError(
                400,
                "required_approvals must be one of "
                + ", ".join(str(v) for v in ALLOWED_REQUIRED_APPROVALS),
            )
        if (
            not isinstance(timeout_seconds, int)
            or isinstance(timeout_seconds, bool)
            or timeout_seconds <= 0
        ):
            raise ServiceError(400, "timeout_seconds must be a positive integer")
        policy = {
            "wallet_id": wallet_id,
            "required_approvals": required_approvals,
            "timeout_seconds": timeout_seconds,
        }
        # 同值更新也成功并记录（operation 区分首设/更新）
        old_policy = self._store.get_policy(wallet_id)
        operation = "created" if old_policy is None else "updated"
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            self._store.save_policy(wallet_id, policy)
            event = self._audit_event(
                audit.TYPE_POLICY_UPDATED,
                details={
                    "required_approvals": required_approvals,
                    "timeout_seconds": timeout_seconds,
                    "operation": operation,
                },
            )
            try:
                self._emit(wallet_id, event)
            except BaseException:
                # 状态/事件原子：事件未落盘则回滚策略状态
                if old_policy is None:
                    self._store.delete_policy(wallet_id)
                else:
                    self._store.save_policy(wallet_id, old_policy)
                raise
        return policy

    # ---- 冷热钱包交易策略 -------------------------------------------------

    @staticmethod
    def _validate_transaction_policy(
        mode: object, max_delta: object, allowed_assets: object
    ) -> None:
        """校验交易策略请求体：类型、空值、重复或非法资产一律 400。"""
        if not isinstance(mode, str) or mode not in TRANSACTION_POLICY_MODES:
            raise ServiceError(
                400,
                "mode must be one of "
                + ", ".join(TRANSACTION_POLICY_MODES),
            )
        # bool 是 int 的子类，必须先排除
        if (
            not isinstance(max_delta, int)
            or isinstance(max_delta, bool)
            or max_delta <= 0
        ):
            raise ServiceError(400, "max_delta must be a positive integer")
        if not isinstance(allowed_assets, list) or not allowed_assets:
            raise ServiceError(
                400, "allowed_assets must be a non-empty list"
            )
        seen: set[str] = set()
        for index, asset in enumerate(allowed_assets):
            if not isinstance(asset, str) or not ROTATION_ID_RE.match(asset):
                raise ServiceError(
                    400,
                    f"allowed_assets[{index}] must match "
                    "[A-Za-z0-9_-]{1,128}",
                )
            if asset in seen:
                raise ServiceError(
                    400, f"allowed_assets[{index}] duplicates a prior asset"
                )
            seen.add(asset)

    def put_transaction_policy(
        self,
        wallet_id: str,
        mode: object,
        max_delta: object,
        allowed_assets: object,
    ) -> dict:
        """设置（或覆盖）钱包的冷热钱包交易策略。

        成功 200 返回与请求体同形的 {mode, max_delta, allowed_assets}；
        钱包不存在 404；类型、空值、重复或非法资产 400。策略状态与
        transaction_policy_updated 事件在每钱包事务锁内原子持久化，
        同值更新也记事件（details 即策略三项）。
        """
        self._get_wallet_or_404(wallet_id)
        self._validate_transaction_policy(mode, max_delta, allowed_assets)
        policy = {
            "mode": mode,
            "max_delta": max_delta,
            "allowed_assets": list(allowed_assets),
        }
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            old_policy = self._store.get_transaction_policy(wallet_id)
            self._store.save_transaction_policy(wallet_id, policy)
            event = self._audit_event(
                audit.TYPE_TRANSACTION_POLICY_UPDATED,
                details={
                    "mode": mode,
                    "max_delta": max_delta,
                    "allowed_assets": list(allowed_assets),
                },
            )
            try:
                self._emit(wallet_id, event)
            except BaseException:
                # 状态/事件原子：事件未落盘则回滚策略状态
                if old_policy is None:
                    self._store.delete_transaction_policy(wallet_id)
                else:
                    self._store.save_transaction_policy(
                        wallet_id, old_policy
                    )
                raise
        return policy

    def get_transaction_policy(self, wallet_id: str) -> dict:
        """读取交易策略：已配置 200 同体，未配置 404。"""
        self._get_wallet_or_404(wallet_id)
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            policy = self._store.get_transaction_policy(wallet_id)
        if policy is None:
            raise ServiceError(
                404, f"wallet {wallet_id!r} has no transaction policy"
            )
        return {
            "mode": policy["mode"],
            "max_delta": policy["max_delta"],
            "allowed_assets": list(policy["allowed_assets"]),
        }

    # ---- 签名请求审批单 ---------------------------------------------------

    @staticmethod
    def _request_view(record: dict) -> dict:
        """审批单对外视图（GET/POST 响应体共用）。"""
        return {
            "id": record["id"],
            "message": record["message"],
            "state": record["state"],
            "approvers": list(record["approvers"]),
            "count": len(record["approvers"]),
            "req": record["req"],
            "t0": record["t0"],
            "t1": record["t1"],
            "reason": record["reason"],
        }

    def _expire_if_needed(self, wallet_id: str, record: dict) -> dict:
        """懒过期：任何操作前把已超时的 pending 单持久化为 expired，
        并原子记录一次 request_expired 事件。调用方须持有该钱包事务锁。
        事件追加失败时回滚为原 pending 状态后向上抛出。"""
        if record["state"] == "pending" and (
            datetime.now(timezone.utc) >= _parse_iso(record["t1"])
        ):
            expired = dict(record)
            expired["state"] = "expired"
            self._store.update_request(wallet_id, record["id"], expired)
            try:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_REQUEST_EXPIRED,
                        request_id=record["id"],
                        details={"state": "expired"},
                    ),
                )
            except BaseException:
                self._store.update_request(wallet_id, record["id"], record)
                raise
            record = expired
        return record

    def _fetch_request_or_404(self, wallet_id: str, request_id: str) -> dict:
        """只读取审批单（404），不做懒过期；调用方自行在钱包事务锁内过期。"""
        try:
            record = self._store.get_request(wallet_id, request_id)
        except CorruptDataError:
            raise
        except ValueError:
            raise ServiceError(400, "invalid signing_request_id")
        if record is None:
            raise ServiceError(
                404, f"signing request {request_id!r} not found"
            )
        return record

    @staticmethod
    def _validate_request_body(request_id: object, message: object) -> None:
        if (
            not isinstance(request_id, str)
            or not request_id
            or not request_id.strip()
        ):
            raise ServiceError(
                400, "signing_request_id must be a non-empty string"
            )
        if not isinstance(message, str) or not message or not message.strip():
            raise ServiceError(400, "message must be a non-empty string")

    def create_sign_request(
        self, wallet_id: str, request_id: object, message: object
    ) -> tuple[int, dict]:
        """返回 (HTTP 状态码, 响应体)。"""
        self._get_wallet_or_404(wallet_id)
        self._validate_request_body(request_id, message)
        try:
            self._store.get_request(wallet_id, request_id)
        except CorruptDataError:
            raise
        except ValueError:
            raise ServiceError(400, "invalid signing_request_id")
        policy = self._store.get_policy(wallet_id)
        if policy is None:
            raise ServiceError(
                409, f"wallet {wallet_id!r} has no approval policy"
            )

        now = datetime.now(timezone.utc)
        record = {
            "id": request_id,
            "message": message,
            "state": "pending",
            "approvers": [],
            "req": policy["required_approvals"],
            "t0": now.isoformat().replace("+00:00", "Z"),
            "t1": (now + timedelta(seconds=policy["timeout_seconds"]))
            .isoformat()
            .replace("+00:00", "Z"),
            "reason": None,
        }
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            existing = self._store.create_request(wallet_id, request_id, record)
            if existing is not None:
                # 重放（无论同文幂等还是异文 409）均不记事件、不改状态。
                # POST 不是懒过期触发点：原样返回磁盘中持久化的状态
                # （pending/approved/rejected/expired/signed），绝不在响应里
                # 把磁盘仍是 pending 的单临时呈现成 expired。
                if existing["message"] != message:
                    raise ServiceError(
                        409,
                        f"signing request {request_id!r} already exists "
                        "with a different message",
                    )
                # 同 id 同文：幂等重放
                return 200, self._request_view(existing)
            # 首次创建：状态 + C 事件原子
            event = self._audit_event(
                audit.TYPE_REQUEST_CREATED,
                request_id=request_id,
                details={"message": message},
            )
            try:
                self._emit(wallet_id, event)
            except BaseException:
                self._store.delete_request(wallet_id, request_id)
                raise
        return 201, self._request_view(record)

    def get_sign_request(self, wallet_id: str, request_id: str) -> dict:
        self._get_wallet_or_404(wallet_id)
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            record = self._fetch_request_or_404(wallet_id, request_id)
            record = self._expire_if_needed(wallet_id, record)
            return self._request_view(record)

    # ---- 审计事件查询 ---------------------------------------------------

    #: 审计事件查询每页上限与默认条数
    AUDIT_DEFAULT_LIMIT = 1000
    AUDIT_MAX_LIMIT = 1000

    @staticmethod
    def _parse_positive_int(value: object, name: str) -> int:
        """from_seq/limit 必须是正整数（bool/浮点/带符号/缺失均拒绝）。"""
        if isinstance(value, str):
            text = value.strip()
            if not text.isdigit():
                raise ServiceError(400, f"{name} must be a positive integer")
            value = int(text)
        if (
            not isinstance(value, int)
            or isinstance(value, bool)
            or value < 1
        ):
            raise ServiceError(400, f"{name} must be a positive integer")
        return value

    def get_audit_events(
        self,
        wallet_id: str,
        from_seq: object = None,
        limit: object = None,
    ) -> dict:
        """返回 {wallet_id, events}（seq 升序）。

        纯只读：不触发 pending 审批单懒过期、不写任何状态/事件、不分配
        seq。但与其他所有访问钱包状态的路由一致，必须在该钱包事务锁内
        先自愈他进程崩溃遗留的轮换/资产提交残留，再读取审计：恢复无法
        对账（RecoveryError/OSError/CorruptDataError）时由调用方转 503，
        绝不返回可能半完成的公钥/余额/version 之外的不一致现场。"""
        self._get_wallet_or_404(wallet_id)
        seq = (
            1
            if from_seq is None
            else self._parse_positive_int(from_seq, "from_seq")
        )
        size = (
            self.AUDIT_DEFAULT_LIMIT
            if limit is None
            else self._parse_positive_int(limit, "limit")
        )
        if size > self.AUDIT_MAX_LIMIT:
            raise ServiceError(
                400, f"limit must be at most {self.AUDIT_MAX_LIMIT}"
            )
        with self._wallet_lock(wallet_id):
            # 只读自愈：把可恢复的崩溃现场对账到一致，但绝不记事件、
            # 绝不触发审批单懒过期。
            self._heal_wallet(wallet_id)
            events = self._audit.list_events(
                wallet_id, from_seq=seq, limit=size
            )
        return {"wallet_id": wallet_id, "events": events}

    # ---- 份额轮换 ---------------------------------------------------------

    @staticmethod
    def _rotation_view(record: dict) -> dict:
        """轮换记录对外视图（只含公钥与标识，绝不含私钥）。"""
        return {
            "rotation_id": record["rotation_id"],
            "state": record["state"],
            "share_ids": list(record["share_ids"]),
            "public_key": record["public_key"],
        }

    @staticmethod
    def _validate_rotation_id(rotation_id: object) -> None:
        if not isinstance(rotation_id, str) or not ROTATION_ID_RE.match(
            rotation_id
        ):
            raise ServiceError(
                400, "rotation_id must match [A-Za-z0-9_-]{1,128}"
            )

    def create_share_rotation(
        self, wallet_id: str, rotation_id: object
    ) -> tuple[int, dict]:
        """准备一次份额轮换：生成两份新份额，私钥只落暂存文件。

        返回 (HTTP 状态码, 响应体)。同 rotation_id 重放返回 200 且不重新
        生成；每钱包同时只允许一个 prepared 轮换，冲突返回 409。
        """
        self._get_wallet_or_404(wallet_id)
        self._validate_rotation_id(rotation_id)
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            existing = self._store.get_rotation(wallet_id, rotation_id)
            if existing is not None:
                # 幂等重放：原样返回，不重新生成、不记事件
                return 200, self._rotation_view(existing)
            for record in self._store.list_rotations(wallet_id):
                if record.get("state") in ("prepared", "activating"):
                    raise ServiceError(
                        409,
                        f"wallet {wallet_id!r} already has a prepared "
                        "share rotation",
                    )
            share_ids = [
                f"{rotation_id}-share-1",
                f"{rotation_id}-share-2",
            ]
            share_keys = [crypto.generate_share_key(sid) for sid in share_ids]
            public_key = crypto.combine_public_keys(
                [k.public_bytes for k in share_keys]
            ).hex()
            record = {
                "rotation_id": rotation_id,
                "state": "prepared",
                "share_ids": share_ids,
                "public_key": public_key,
                "created_at": _utc_now_iso(),
            }
            try:
                # 新份额私钥只写入暂存文件（一份一个文件），激活前绝不
                # 触碰在用份额与钱包元数据
                for key in share_keys:
                    self._store.save_staging_share(
                        wallet_id,
                        rotation_id,
                        {
                            "share_id": key.share_id,
                            "public_key": key.public_bytes.hex(),
                            # 仅该份额自己的私钥；系统中不存在完整私钥
                            "private_key": key.private_bytes.hex(),
                        },
                    )
                self._store.create_rotation(wallet_id, rotation_id, record)
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SHARE_ROTATION_PREPARED,
                        details={
                            "rotation_id": rotation_id,
                            "share_ids": share_ids,
                            "public_key": public_key,
                        },
                    ),
                )
            except BaseException:
                # 状态/事件原子：事件未落盘则回滚轮换记录与暂存文件
                self._store.delete_rotation(wallet_id, rotation_id)
                self._store.delete_staging(wallet_id, rotation_id)
                raise
        return 201, self._rotation_view(record)

    def get_share_rotation(self, wallet_id: str, rotation_id: str) -> dict:
        self._get_wallet_or_404(wallet_id)
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 锁内读取：并发激活期间不会读到瞬态 activating
            try:
                record = self._store.get_rotation(wallet_id, rotation_id)
            except CorruptDataError:
                raise
            except ValueError:
                raise ServiceError(400, "invalid rotation_id")
            if record is None:
                raise ServiceError(
                    404, f"share rotation {rotation_id!r} not found"
                )
            return self._rotation_view(record)

    def activate_share_rotation(
        self, wallet_id: str, rotation_id: str
    ) -> tuple[int, dict]:
        """激活一次已准备的轮换：锁内替换份额文件、钱包公钥与轮换状态。

        仅 prepared 可激活（201）；active 重放返回 200；其余状态 409。
        失败时回滚份额文件、公钥与状态并清理备份；激活成功后删除暂存。
        """
        self._get_wallet_or_404(wallet_id)
        self._validate_rotation_id(rotation_id)
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            record = self._store.get_rotation(wallet_id, rotation_id)
            if record is None:
                raise ServiceError(
                    404, f"share rotation {rotation_id!r} not found"
                )
            if record["state"] == "active":
                # 幂等重放：不重复替换、不记事件
                return 200, self._rotation_view(record)
            if record["state"] != "prepared":
                raise ServiceError(
                    409,
                    f"share rotation {rotation_id!r} is "
                    f"{record['state']}, not prepared",
                )

            # 锁内重读钱包元数据，拿到当前在用份额与公钥
            wallet = self._store.get_wallet(wallet_id)
            if wallet is None:
                raise ServiceError(404, f"wallet {wallet_id!r} not found")
            previous_public_key = wallet["public_key"]
            old_share_ids = [s["share_id"] for s in wallet["shares"]]
            old_share_records = []
            for share_id in old_share_ids:
                share_record = self._store.get_share(wallet_id, share_id)
                if share_record is None:
                    raise ServiceError(
                        409, f"wallet {wallet_id!r} share files are incomplete"
                    )
                old_share_records.append(share_record)
            new_share_records = []
            for share_id in record["share_ids"]:
                staged = self._store.get_staging_share(
                    wallet_id, rotation_id, share_id
                )
                if staged is None:
                    raise ServiceError(
                        409,
                        f"share rotation {rotation_id!r} staging files "
                        "are incomplete",
                    )
                new_share_records.append(staged)

            new_meta = dict(wallet)
            new_meta["shares"] = [
                {"share_id": r["share_id"], "public_key": r["public_key"]}
                for r in new_share_records
            ]
            new_meta["public_key"] = record["public_key"]
            active_record = dict(record)
            active_record["state"] = "active"
            active_record["previous_public_key"] = previous_public_key

            try:
                # 先落 activating 标记与旧份额/元数据备份：崩溃后启动
                # 恢复据此回滚
                activating = dict(record)
                activating["state"] = "activating"
                activating["previous_public_key"] = previous_public_key
                self._store.update_rotation(wallet_id, rotation_id, activating)
                self._store.save_activation_backups(
                    wallet_id, rotation_id, old_share_records, wallet
                )
                # 锁内替换：新份额文件、钱包 shares/public_key、轮换状态
                for share_record in new_share_records:
                    self._store.save_share(wallet_id, share_record)
                self._store.save_wallet_meta(wallet_id, new_meta)
                for share_id in old_share_ids:
                    self._store.delete_share(wallet_id, share_id)
                self._store.update_rotation(
                    wallet_id, rotation_id, active_record
                )
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SHARE_ROTATION_ACTIVATED,
                        details={
                            "rotation_id": rotation_id,
                            "share_ids": list(record["share_ids"]),
                            "public_key": record["public_key"],
                            "previous_public_key": previous_public_key,
                        },
                    ),
                )
            except BaseException:
                # 以激活事件是否真正落盘为唯一判据，而不是是否抛错：
                landed = self._activated_rotations(wallet_id).get(rotation_id)
                if landed is not None:
                    # 事件已落盘（提交不可撤回）：前滚为唯一 active 并
                    # 清理残留，绝不回滚、不重复记事件
                    self._store.forward_complete_activation(
                        wallet_id, active_record, landed
                    )
                    return 201, self._rotation_view(active_record)
                # 事件未落盘：回滚份额文件、公钥与状态，清理激活备份
                # （保留暂存的新份额文件，prepared 轮换可重试激活）
                self._store.rollback_activation_files(wallet_id, record)
                self._store.update_rotation(wallet_id, rotation_id, record)
                self._store.delete_activation_backups(
                    wallet_id, rotation_id
                )
                raise
            # 激活成功：删除暂存的新份额文件与备份。此清理非提交点，
            # 若清理 I/O 失败也不改结果（事件已落盘，激活已生效），
            # 残留由重放/下一次持锁访问/重启自愈前滚时清掉。
            try:
                self._store.delete_staging(wallet_id, rotation_id)
            except OSError:
                pass
        return 201, self._rotation_view(active_record)

    # ---- 资产账本 ---------------------------------------------------------

    @staticmethod
    def _validate_operation_id(operation_id: object) -> None:
        if not isinstance(operation_id, str) or not ROTATION_ID_RE.match(
            operation_id
        ):
            raise ServiceError(
                400, "operation_id must match [A-Za-z0-9_-]{1,128}"
            )

    @staticmethod
    def _validate_asset_id(asset_id: object) -> None:
        if not isinstance(asset_id, str) or not ROTATION_ID_RE.match(
            asset_id
        ):
            raise ServiceError(
                400, "asset_id must match [A-Za-z0-9_-]{1,128}"
            )

    @staticmethod
    def _validate_delta(delta: object) -> None:
        # bool 是 int 的子类，必须先排除；0 不是合法的资产变动
        if not isinstance(delta, int) or isinstance(delta, bool) or delta == 0:
            raise ServiceError(400, "delta must be a non-zero integer")

    def create_asset_operation(
        self,
        wallet_id: str,
        operation_id: object,
        asset_id: object,
        delta: object,
    ) -> tuple[int, dict]:
        """创建一条资产操作（pending）。返回 (HTTP 状态码, 响应体 R)。

        首次创建 201；同 operation_id 同参数幂等重放 200（返回当前记录，
        不重复记事件、不再按当前策略校验）；同 operation_id 异参数 409。
        创建本身不记审计事件。

        钱包配置了冷热钱包交易策略时，**仅首次创建**按创建时刻的策略
        检查：asset_id 必须在 allowed_assets 白名单内且
        ``abs(delta) <= max_delta``，否则 409 且账本/version/状态/审计/
        幂等结果均不变（检查发生在任何写入之前）。策略后续更新不影响
        已存在的 pending 操作；未配置策略时行为完全不变。
        """
        self._get_wallet_or_404(wallet_id)
        self._validate_operation_id(operation_id)
        self._validate_asset_id(asset_id)
        self._validate_delta(delta)
        with self._wallet_lock(wallet_id):
            # 快照前先自愈他进程崩溃遗留的提交意图，balance/version 才准确
            self._heal_wallet(wallet_id)
            existing = self._store.get_asset_operation(
                wallet_id, operation_id
            )
            if existing is not None:
                # 重放：原样返回磁盘中的当前记录，不按更新后的策略重新
                # 校验、不改状态、不记事件（幂等结果不变）
                if (
                    existing.get("asset_id") != asset_id
                    or existing.get("delta") != delta
                ):
                    raise ServiceError(
                        409,
                        f"asset operation {operation_id!r} already exists "
                        "with different parameters",
                    )
                return 200, existing
            # 首次创建：按创建时刻的交易策略检查白名单与单笔变动上限
            policy = self._store.get_transaction_policy(wallet_id)
            if policy is not None:
                if asset_id not in policy["allowed_assets"]:
                    raise ServiceError(
                        409,
                        f"asset {asset_id!r} is not allowed by the "
                        "transaction policy",
                    )
                if abs(delta) > policy["max_delta"]:
                    raise ServiceError(
                        409,
                        f"abs(delta)={abs(delta)} exceeds transaction "
                        f"policy max_delta={policy['max_delta']}",
                    )
            # R 的 balance/version 快照资产在创建时刻的账本状态
            asset = self._store.get_asset(wallet_id, asset_id)
            record = {
                "operation_id": operation_id,
                "asset_id": asset_id,
                "state": "pending",
                "delta": delta,
                "balance": asset["balance"] if asset is not None else 0,
                "version": asset["version"] if asset is not None else 0,
            }
            # 锁内已确认不存在；存储层仍原子查重兜底
            self._store.create_asset_operation(wallet_id, operation_id, record)
        return 201, record

    # ---- 资产提交的崩溃恢复 ----------------------------------------------

    def _recover_wallet_asset_commits(self, wallet_id: str) -> None:
        """恢复某钱包全部未完成的资产提交事务（调用方须持有钱包事务锁）。

        以 asset_operation_committed 事件是否已持久化作为唯一提交判据：
        - 事件在：提交已生效，按事件 details（即 committed 视图 R）把账本
          前滚补齐为一致的 committed 结果，再删意图（幂等，余额/版本按 R
          绝对值校正，不重复应用 delta）；
        - 事件不在：提交未生效，按意图记录的提交前快照把操作恢复为
          pending、资产恢复提交前 balance/version（提交前不存在则删除
          资产条目），再删意图。事件从未分配 seq，故无 seq 缺口。
        恢复本身不记任何审计事件。任一条意图无法对账到一致状态都抛
        RecoveryError，由调用方阻止就绪/返回 503，绝不静默跳过。
        """
        for operation_id, intent in self._store.list_asset_intents(wallet_id):
            self._resolve_asset_commit_intent(wallet_id, operation_id, intent)

    def _resolve_asset_commit_intent(
        self, wallet_id: str, operation_id: str, intent: object
    ) -> Optional[dict]:
        """对账单条提交意图，返回 committed 视图 R（前滚）或 None（回滚）。"""
        event = self._audit.find_event_by_request(
            wallet_id,
            audit.TYPE_ASSET_OPERATION_COMMITTED,
            operation_id,
        )
        if event is not None:
            details = event.get("details")
            asset_id = details.get("asset_id") if isinstance(details, dict) else None
            balance = details.get("balance") if isinstance(details, dict) else None
            version = details.get("version") if isinstance(details, dict) else None
            delta = details.get("delta") if isinstance(details, dict) else None
            # 仅当前滚目标是形状完整的 R 时才补齐；事件损坏（原子写使
            # 正常崩溃不会出现，此处只防御外部篡改）无法安全对账，fail-closed。
            if (
                not isinstance(details, dict)
                or not isinstance(asset_id, str)
                or not isinstance(delta, int)
                or isinstance(delta, bool)
                or not isinstance(balance, int)
                or isinstance(balance, bool)
                or not isinstance(version, int)
                or isinstance(version, bool)
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} asset operation "
                    f"{operation_id!r} committed event is malformed"
                )
            committed_record = {
                "operation_id": operation_id,
                "asset_id": asset_id,
                "state": "committed",
                "delta": delta,
                "balance": balance,
                "version": version,
            }
            asset_record = {"balance": balance, "version": version}
            # 按事件 R 绝对补齐：即使账本已部分落盘也不重复加 delta、
            # 不产生重复 version
            self._store.commit_asset_operation(
                wallet_id,
                operation_id,
                committed_record,
                asset_id,
                asset_record,
            )
            self._store.delete_asset_commit_intent(wallet_id, operation_id)
            return committed_record

        # 事件未持久化：提交未生效，回滚为 pending 与提交前资产状态
        if not isinstance(intent, dict):
            # 意图不可解析（正常原子写不会出现）：若账本仍是 pending/无操作，
            # 说明本就处于中止态，仅清理意图；若已被改成 committed 却无
            # 事件，且没有可解析意图恢复提交前状态，无法安全对账，fail-closed。
            op = self._store.get_asset_operation(wallet_id, operation_id)
            if op is None or op.get("state") == "pending":
                self._store.delete_asset_commit_intent(wallet_id, operation_id)
                return None
            raise RecoveryError(
                f"wallet {wallet_id!r} asset operation {operation_id!r} "
                "committed without event and intent is unreadable"
            )
        pending = intent.get("pending")
        asset_id = intent.get("asset_id")
        old_asset = intent.get("old_asset")
        if not isinstance(pending, dict) or not isinstance(asset_id, str):
            raise RecoveryError(
                f"wallet {wallet_id!r} asset operation {operation_id!r} "
                "intent is malformed"
            )
        self._store.restore_asset_operation(
            wallet_id,
            operation_id,
            pending,
            asset_id,
            old_asset if isinstance(old_asset, dict) else None,
        )
        self._store.delete_asset_commit_intent(wallet_id, operation_id)
        return None

    def commit_asset_operation(
        self, wallet_id: str, operation_id: str
    ) -> tuple[int, dict]:
        """提交一条 pending 的资产操作（可恢复事务）。返回 (状态码, R)。

        事务顺序（全部在每钱包跨进程事务锁内）::

            1. 写提交意图（记录 committed 结果 R 与提交前资产快照）
            2. 原子提交账本：操作转 committed、balance 改、version+1
            3. 追加唯一的 asset_operation_committed 事件（details=R，
               request_id=operation_id）
            4. 删除提交意图

        崩溃恢复以事件是否落盘为准：事件在则前滚补齐，事件不在则回滚
        pending 与提交前余额/版本。故任何阶段被强制终止，重启后都不会
        出现提交无事件、事件与余额不符、重复 version 或重复事件。

        余额不足 409 且无副作用；committed 重放 200 同体，不改账、不记事件。
        """
        self._get_wallet_or_404(wallet_id)
        self._validate_operation_id(operation_id)
        with self._wallet_lock(wallet_id):
            # 先自愈他进程崩溃遗留的任何提交意图，再基于一致账本判定，
            # 绝不基于半完成状态提交。
            self._heal_wallet(wallet_id)

            record = self._store.get_asset_operation(wallet_id, operation_id)
            if record is None:
                raise ServiceError(
                    404, f"asset operation {operation_id!r} not found"
                )
            if record["state"] == "committed":
                # 幂等重放：不重复改账、不记事件
                return 200, record
            if record["state"] != "pending":
                raise ServiceError(
                    409,
                    f"asset operation {operation_id!r} is "
                    f"{record['state']}, not pending",
                )
            asset_id = record["asset_id"]
            asset = self._store.get_asset(wallet_id, asset_id)
            old_balance = asset["balance"] if asset is not None else 0
            old_version = asset["version"] if asset is not None else 0
            new_balance = old_balance + record["delta"]
            if new_balance < 0:
                # 余额不足：状态不变（仍 pending），可重试，不记事件
                raise ServiceError(
                    409,
                    f"asset {asset_id!r} has insufficient balance "
                    "for this operation",
                )
            new_version = old_version + 1
            committed_record = {
                "operation_id": operation_id,
                "asset_id": asset_id,
                "state": "committed",
                "delta": record["delta"],
                "balance": new_balance,
                "version": new_version,
            }
            asset_record = {"balance": new_balance, "version": new_version}
            # 意图只含标识与整数，不含任何私钥材料
            intent = {
                "operation_id": operation_id,
                "asset_id": asset_id,
                "delta": record["delta"],
                "old_asset": asset,
                "pending": record,
                "new_balance": new_balance,
                "new_version": new_version,
            }
            try:
                self._store.write_asset_commit_intent(
                    wallet_id, operation_id, intent
                )
                self._store.commit_asset_operation(
                    wallet_id,
                    operation_id,
                    committed_record,
                    asset_id,
                    asset_record,
                )
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_ASSET_OPERATION_COMMITTED,
                        request_id=operation_id,
                        details=committed_record,
                    ),
                )
            except BaseException:
                # 普通写入/事件追加失败：以事件是否真正落盘为准对账。
                # 事件在（如落盘成功但返回阶段报错）则前滚为唯一 committed，
                # 绝不重复记事件；事件不在则回滚 pending 与提交前余额/版本，
                # 事件从未分配 seq，故无事件、无 seq 缺口，可重试。
                landed = self._audit.find_event_by_request(
                    wallet_id,
                    audit.TYPE_ASSET_OPERATION_COMMITTED,
                    operation_id,
                )
                if landed is not None:
                    self._store.commit_asset_operation(
                        wallet_id,
                        operation_id,
                        committed_record,
                        asset_id,
                        asset_record,
                    )
                    self._store.delete_asset_commit_intent(
                        wallet_id, operation_id
                    )
                    return 201, committed_record
                self._store.restore_asset_operation(
                    wallet_id, operation_id, record, asset_id, asset
                )
                self._store.delete_asset_commit_intent(wallet_id, operation_id)
                raise
            self._store.delete_asset_commit_intent(wallet_id, operation_id)
        return 201, committed_record

    def get_asset(self, wallet_id: str, asset_id: str) -> dict:
        """查询某资产的账本状态（balance/version）。

        在每钱包事务锁内读取：提交事务进行中（账本已改、事件尚未落盘）的
        查询会被挡到事务结束，绝不会读到随后可能回滚的半完成余额。
        """
        self._get_wallet_or_404(wallet_id)
        self._validate_asset_id(asset_id)
        with self._wallet_lock(wallet_id):
            # 查询前先自愈他进程崩溃遗留的提交意图，绝不返回半完成余额
            self._heal_wallet(wallet_id)
            asset = self._store.get_asset(wallet_id, asset_id)
            if asset is None:
                raise ServiceError(404, f"asset {asset_id!r} not found")
            return {
                "asset_id": asset_id,
                "balance": asset["balance"],
                "version": asset["version"],
            }

    # ---- 批准 / 拒绝 -----------------------------------------------------

    @staticmethod
    def _validate_approver_id(approver_id: object) -> None:
        if (
            not isinstance(approver_id, str)
            or isinstance(approver_id, bool)
            or not approver_id
            or not approver_id.strip()
        ):
            raise ServiceError(
                400, "approver_id must be a non-empty string"
            )

    @staticmethod
    def _validate_reason(reason: object) -> None:
        if reason is None:
            return
        if not isinstance(reason, str) or isinstance(reason, bool):
            raise ServiceError(400, "reason must be a string")
        if not reason.strip():
            raise ServiceError(400, "reason must be non-blank")
        if len(reason) > MAX_REASON_LENGTH:
            raise ServiceError(
                400, f"reason must be at most {MAX_REASON_LENGTH} characters"
            )

    def _decide(
        self,
        wallet_id: str,
        request_id: str,
        approver_id: object,
        reason: object,
        action: str,
    ) -> dict:
        self._get_wallet_or_404(wallet_id)
        self._validate_approver_id(approver_id)
        self._validate_reason(reason)
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            record = self._fetch_request_or_404(wallet_id, request_id)
            # 懒过期可能在此原子记一次 E；过期后操作落入终态分支（409、不记 A/R）
            record = self._expire_if_needed(wallet_id, record)
            if record["state"] != "pending":
                raise ServiceError(
                    409,
                    f"signing request {request_id!r} is {record['state']}, "
                    "not pending",
                )

            if action == "approve":
                # 同一 approver 重复批准不计数、不记事件（幂等 200）
                if approver_id in record["approvers"]:
                    return self._request_view(record)
                new_record = dict(record)
                new_record["approvers"] = list(record["approvers"])
                new_record["approvers"].append(approver_id)
                if reason is not None:
                    new_record["reason"] = reason
                reached = len(new_record["approvers"]) >= new_record["req"]
                if reached:
                    new_record["state"] = "approved"
                self._store.update_request(wallet_id, request_id, new_record)
                event = self._audit_event(
                    audit.TYPE_REQUEST_APPROVED,
                    request_id=request_id,
                    actor_id=approver_id,
                    reason=reason,
                    details={
                        "count": len(new_record["approvers"]),
                        "req": new_record["req"],
                        "state": new_record["state"],
                    },
                )
                try:
                    self._emit(wallet_id, event)
                except BaseException:
                    self._store.update_request(wallet_id, request_id, record)
                    raise
                return self._request_view(new_record)

            # reject：任何一名审批人拒绝即终态（首批）
            new_record = dict(record)
            new_record["state"] = "rejected"
            if reason is not None:
                new_record["reason"] = reason
            self._store.update_request(wallet_id, request_id, new_record)
            event = self._audit_event(
                audit.TYPE_REQUEST_REJECTED,
                request_id=request_id,
                actor_id=approver_id,
                reason=reason,
                details={
                    "count": len(new_record["approvers"]),
                    "req": new_record["req"],
                    "state": "rejected",
                },
            )
            try:
                self._emit(wallet_id, event)
            except BaseException:
                self._store.update_request(wallet_id, request_id, record)
                raise
            return self._request_view(new_record)

    def approve(
        self,
        wallet_id: str,
        request_id: str,
        approver_id: object,
        reason: object = None,
    ) -> dict:
        return self._decide(wallet_id, request_id, approver_id, reason, "approve")

    def reject(
        self,
        wallet_id: str,
        request_id: str,
        approver_id: object,
        reason: object = None,
    ) -> dict:
        return self._decide(wallet_id, request_id, approver_id, reason, "reject")

    # ---- 份额签名聚合 ---------------------------------------------------

    def sign(
        self,
        wallet_id: str,
        signing_request_id: object,
        message: object,
        signatures: object,
    ) -> tuple[int, dict]:
        """返回 (HTTP 状态码, 响应体)。"""
        try:
            wallet = self._store.get_wallet(wallet_id)
        except CorruptDataError:
            raise
        except ValueError:
            raise ServiceError(400, "invalid wallet_id")
        if wallet is None:
            raise ServiceError(404, f"wallet {wallet_id!r} not found")

        if (
            not isinstance(signing_request_id, str)
            or not signing_request_id
        ):
            raise ServiceError(
                400, "signing_request_id must be a non-empty string"
            )
        if not isinstance(message, str):
            raise ServiceError(400, "message must be a string")
        if not isinstance(signatures, list) or len(signatures) != REQUIRED_SHARES:
            raise ServiceError(
                400, f"exactly {REQUIRED_SHARES} share signatures are required"
            )

        with self._wallet_lock(wallet_id):
            # 先自愈他进程崩溃遗留的激活/提交现场，绝不基于半完成的钱包
            # 公钥或份额做校验。
            self._heal_wallet(wallet_id)
            # 锁内重读钱包元数据：份额轮换激活后，未首签的请求必须用新的
            # share_ids 与公钥校验，旧份额一律 400。
            wallet = self._store.get_wallet(wallet_id)
            if wallet is None:
                raise ServiceError(404, f"wallet {wallet_id!r} not found")
            expected_share_ids = [s["share_id"] for s in wallet["shares"]]
            share_pub = {s["share_id"]: s["public_key"] for s in wallet["shares"]}
            # 幂等查重的唯一检查点：必须在每钱包事务锁内、且在任何份额校验
            # 之前。重放直接返回磁盘上已提交的签名，不校验签名、不触发懒
            # 过期、不记事件。这把锁同时挡住首签事务尚未提交完成的并发
            # 请求，使重放永远读不到“签名已落盘但审批单/事件未提交”的
            # 半完成数据，保证并发重放只有一个首次结果。
            try:
                existing = self._store.get_signature(
                    wallet_id, signing_request_id
                )
            except CorruptDataError:
                raise
            except ValueError:
                raise ServiceError(400, "invalid signing_request_id")
            if existing is not None:
                return 200, {"signature": existing["signature"]}

            submitted: dict[str, bytes] = {}
            for index, item in enumerate(signatures):
                if not isinstance(item, dict):
                    raise ServiceError(400, f"signatures[{index}] must be an object")
                share_id = item.get("share_id")
                signature_hex = item.get("signature")
                if not isinstance(share_id, str) or share_id not in share_pub:
                    raise ServiceError(400, f"signatures[{index}] has unknown share_id")
                if not isinstance(signature_hex, str):
                    raise ServiceError(400, f"signatures[{index}].signature must be hex")
                try:
                    signature_bytes = bytes.fromhex(signature_hex)
                except ValueError:
                    raise ServiceError(
                        400, f"signatures[{index}].signature must be hex"
                    )
                if share_id in submitted:
                    raise ServiceError(400, "duplicate share_id in signatures")
                submitted[share_id] = signature_bytes

            # 两份必须齐备，且不能夹带未知份额
            if set(submitted) != set(expected_share_ids):
                raise ServiceError(400, "signatures from both share_ids are required")

            payload = crypto.build_payload(signing_request_id, message)
            verified: dict[str, bytes] = {}
            for share_id in expected_share_ids:
                public_bytes = bytes.fromhex(share_pub[share_id])
                if not crypto.verify_share(
                    public_bytes, payload, submitted[share_id]
                ):
                    raise ServiceError(400, f"signature verification failed for {share_id}")
                verified[share_id] = submitted[share_id]

            aggregate = crypto.combine_signatures(
                [verified[sid] for sid in expected_share_ids]
            )
            record = {"message": message, "signature": aggregate.hex()}

            # 审批单要求：
            # - cold 模式：首签必须存在同 id、同 message 且 approved 的审批单。
            #   未配置审批策略（无法创建审批单）、无单或未 approved 一律 409；
            # - hot（或未配交易策略）且配置了审批策略：沿用原审批规则
            #   （无单 404，message 不符/未 approved 409）；
            # - 其余情形不要求审批单，行为不变。
            # 这一步可能原子地把超时 pending 单记一次 E 并转为 expired。
            approval_record = None
            approval_policy = self._store.get_policy(wallet_id)
            transaction_policy = self._store.get_transaction_policy(wallet_id)
            cold_mode = (
                transaction_policy is not None
                and transaction_policy.get("mode") == "cold"
            )
            if cold_mode:
                try:
                    approval_record = self._store.get_request(
                        wallet_id, signing_request_id
                    )
                except CorruptDataError:
                    raise
                except ValueError:
                    raise ServiceError(400, "invalid signing_request_id")
                if approval_record is None:
                    raise ServiceError(
                        409,
                        f"cold wallet requires an approved signing request "
                        f"{signing_request_id!r}",
                    )
            elif approval_policy is not None:
                approval_record = self._fetch_request_or_404(
                    wallet_id, signing_request_id
                )

            if approval_record is not None:
                approval_record = self._expire_if_needed(
                    wallet_id, approval_record
                )
                if approval_record["message"] != message:
                    raise ServiceError(
                        409, "message does not match the signing request"
                    )
                if approval_record["state"] != "approved":
                    raise ServiceError(
                        409,
                        f"signing request {signing_request_id!r} is "
                        f"{approval_record['state']}, not approved",
                    )

            # 事务提交：签名记录、审批单 signed 状态与 request_signed 事件
            # 必须在本钱包事务锁内一致落盘。任一写入或事件追加失败，都
            # 删除本次签名并把审批单恢复为原 approved，绝不留下半完成数据。
            committed = False
            try:
                existing = self._store.save_signature(
                    wallet_id, signing_request_id, record
                )
                if existing is not None:
                    # 兜底：锁内查重已保证不会到达；万一到达按重放处理，
                    # 不动审批单、不记事件。
                    return 200, {"signature": existing["signature"]}

                if approval_record is not None:
                    signed_record = dict(approval_record)
                    signed_record["state"] = "signed"
                    self._store.update_request(
                        wallet_id, signing_request_id, signed_record
                    )

                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_REQUEST_SIGNED,
                        request_id=signing_request_id,
                        details={"message": message, "state": "signed"},
                    ),
                )
                committed = True
            except BaseException:
                if not committed:
                    self._store.delete_signature(
                        wallet_id, signing_request_id
                    )
                    if approval_record is not None:
                        self._store.update_request(
                            wallet_id, signing_request_id, approval_record
                        )
                raise
        return 201, {"signature": aggregate.hex()}

"""测试辅助：在临时目录上构造 service，并启动真实 HTTP 服务器。"""

from __future__ import annotations

import json
import threading
import urllib.error
import urllib.request
from collections.abc import Iterator
from contextlib import contextmanager
from dataclasses import dataclass

from threshold_wallet import crypto
from threshold_wallet.server import create_server
from threshold_wallet.service import WalletService
from threshold_wallet.store import WalletStore


@dataclass
class Harness:
    tmpdir: str
    store: WalletStore
    service: WalletService

    def share_signature(self, wallet_id: str, share_id: str,
                        signing_request_id: str, message: str) -> str:
        """模拟某一份额持有方：用本地份额私钥对拼接载荷签名，返回 hex。"""
        share = self.store.get_share(wallet_id, share_id)
        payload = crypto.build_payload(signing_request_id, message)
        return crypto.sign_share(
            bytes.fromhex(share["private_key"]), payload
        ).hex()

    def two_signatures(self, wallet_id: str, signing_request_id: str,
                       message: str) -> list[dict]:
        return [
            {
                "share_id": sid,
                "signature": self.share_signature(
                    wallet_id, sid, signing_request_id, message
                ),
            }
            for sid in ("share-1", "share-2")
        ]

    def share_private_hex(self, wallet_id: str, share_id: str) -> str:
        return self.store.get_share(wallet_id, share_id)["private_key"]


def make_harness(tmpdir: str) -> Harness:
    store = WalletStore(tmpdir)
    return Harness(tmpdir=tmpdir, store=store, service=WalletService(store))


@dataclass
class RunningServer:
    harness: Harness
    base_url: str
    logs: list[str]
    _httpd: object

    def stop(self) -> None:
        self._httpd.shutdown()
        self._httpd.server_close()

    def request(self, method: str, path: str, body=None):
        data = None
        headers = {"Accept": "application/json"}
        if body is not None:
            data = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(
            self.base_url + path, data=data, method=method, headers=headers
        )
        try:
            with urllib.request.urlopen(req) as resp:
                return resp.status, json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            return exc.code, json.loads(exc.read().decode("utf-8"))


@contextmanager
def http_server(tmpdir: str) -> Iterator[RunningServer]:
    """在后台线程启动真实 HTTP 服务器，端口由内核分配。"""
    harness = make_harness(tmpdir)
    logs: list[str] = []
    httpd = create_server("127.0.0.1", 0, harness.service, trace=logs.append)
    port = httpd.server_address[1]
    thread = threading.Thread(
        target=httpd.serve_forever, kwargs={"poll_interval": 0.02}, daemon=True
    )
    thread.start()
    running = RunningServer(
        harness=harness,
        base_url=f"http://127.0.0.1:{port}",
        logs=logs,
        _httpd=httpd,
    )
    try:
        yield running
    finally:
        running.stop()
        thread.join(timeout=2)

